pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address originalOracle) public {
        // Ensure the oracle address is a contract (needed for valid initialization)
        vm.assume(originalOracle != address(0));
        // Deploy a minimal valid oracle contract
        MockOracle mockOracle = new MockOracle();
        // Use mockOracle as the oracle address, but let the fuzzer vary originalOracle
        // to ensure the property holds generically.
        address oracleToSet = address(mockOracle);

        // Initialize c with a valid payoff definition and the mock oracle
        // Build a valid PayoffDefinition that does not revert
        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(1), // simple transform: identity
            PayoffDefinitionLib.PayoffDirection(1), // NEITHER or valid direction
            bytes30(0)
        );
        // PayoffType and PayoffDirection must have at least one member; we use valid enums
        // Actually, PayoffDefinitionLib.PayoffType is an enum with members; we use value 0
        // which corresponds to the first member.

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TEST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(0),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
                data: bytes30(0)
            }),
            oracle: IOracleProvider(oracleToSet),
            maintenance: UFixed18.wrap(0.1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint256).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18Lib.ZERO,
                maxRate: Fixed18Lib.ZERO,
                targetRate: Fixed18Lib.ZERO,
                targetUtilization: UFixed18Lib.ONE
            })
        });
        vm.prank(address(this)); // controller must be the caller
        c.initialize(info);

        // The property: oracle() must return the address that was passed during initialization
        // In the correct contract, it returns oracleToSet; in the mutant, it returns address(0)
        assertTrue(address(c.oracle()) == oracleToSet);
    }
}

// Minimal mock oracle contract to satisfy isContract check
contract MockOracle {
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({ version: 1, timestamp: block.timestamp, price: Fixed18.wrap(1e18) });
    }
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return this.currentVersion();
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return this.currentVersion();
    }
}

// These type definitions are needed for the test to compile;
// they mirror those used in the original contract.
import {IOracleProvider, IProduct, IController, ICollateral, IIncentivizer, IBeacon, IMultiInvoker} from "../src/C_under_test.sol";
import {UFixed18, UFixed18Lib, Fixed18, Fixed18Lib, JumpRateUtilizationCurve, JumpRateUtilizationCurveLib, PayoffDefinition, PayoffDefinitionLib, Token18} from "../src/C_under_test.sol";

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize with a mock oracle address to set the oracle slot
        // We use a helper contract as the oracle so it is a contract address
        MockOracle oracle = new MockOracle();
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.LONG,
                data: bytes30(0)
            }),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e17),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1000e18),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: Fixed18Lib.ZERO,
                maxRate: Fixed18Lib.ZERO,
                targetRate: Fixed18Lib.ZERO,
                targetUtilization: UFixed18Lib.ONE
            })
        });
        vm.prank(address(this));
        c.initialize(info);
    }
    function testFuzz_property(address fuzzedOracle) public {
        // The fuzzer provides a potential oracle address.
        // We check that after construction and initialization, oracle() returns the address
        // that was actually stored during initialization, not address(0).
        // Since we initialized with a specific address (the MockOracle contract), the invariant
        // is that oracle() returns that address. The mutant returns address(0) regardless,
        // so the assertion will fail for the fuzzer when it checks the stored value.

        // The invariant: oracle() should return the address that was set during initialization.
        // In the reference, this is the MockOracle address. In the mutant, it's address(0).
        // The fuzzer can't change what was stored; it just observes that the getter matches
        // the expected stored value. We read the expected address from the initialization.

        // Since we initialized c with a known MockOracle address, we can assert that
        // oracle() returns that address. The mutant breaks this because it returns address(0).
        IOracleProvider expectedOracle = IOracleProvider(address(new MockOracle()));
        // Note: The actual stored oracle is the MockOracle deployed in setUp, but we can
        // still demonstrate the break: the reference returns the stored address (non-zero),
        // the mutant returns zero. We'll use a known non-zero oracle from setUp indirectly.

        // Actually, we can just assert that oracle() is not address(0) for any valid initialization
        // because the reference always stores the provided oracle address (which must be a contract).
        // The mutant returns address(0) no matter what, so it fails this check.
        assertTrue(address(c.oracle()) != address(0));
    }
}

contract MockOracle is IOracleProvider {
    function sync() external returns (OracleVersion memory) {
        return OracleVersion({ version: 1, timestamp: block.timestamp, price: Fixed18.wrap(1e18) });
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({ version: 1, timestamp: block.timestamp, price: Fixed18.wrap(1e18) });
    }
    function atVersion(uint256) external view returns (OracleVersion memory) {
        return OracleVersion({ version: 1, timestamp: block.timestamp, price: Fixed18.wrap(1e18) });
    }
}

