contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }
    function testFuzz_property(address fuzzOracle) public {
        // Restrict to plausible non-zero contract addresses
        vm.assume(fuzzOracle != address(0));

        // Deploy a minimal contract that fulfills IOracleProvider interface to pass the isContract check
        OracleStub stub = new OracleStub();
        address oracleAddr = fuzzOracle == address(this) ? address(stub) : fuzzOracle;
        vm.assume(oracleAddr.code.length > 0);

        // Build productInfo with the fuzzed oracle address
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TEST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.PASSTHROUGH,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.NEUTRAL,
                data: bytes30(0)
            }),
            oracle: IOracleProvider(oracleAddr),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // Initialize C with the fuzzed oracle via a simulated controller
        IController controller = IController(address(this));
        vm.mockCall(address(controller), abi.encodeWithSelector(IController.isProduct.selector), abi.encode(true));
        vm.mockCall(address(controller), abi.encodeWithSelector(IController.owner.selector), abi.encode(address(this)));
        c.initialize(info);

        // The invariant: after initialization, oracle() must return the address that was passed in
        address returnedOracle = address(c.oracle());
        assertTrue(returnedOracle == oracleAddr);
    }
}

