pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address oracleAddr) public {
        // Ensure the address has code to simulate a valid IOracleProvider
        vm.assume(oracleAddr.code.length > 0);
        // Set up: deploy a minimal contract at oracleAddr (we can't change code of arbitrary addresses,
        // so we use a helper that is a contract and vm.etch its code).
        // But vm.etch is forbidden. Instead, we can use vm.deal and let the fuzzer give us a precompiled address
        // or a contract address. Precompiles have code (e.g., 0x1 to 0x8). We'll restrict to precompiles.
        // Actually, any address with code works. We'll assume the fuzzer can provide such an address.
        // To be safe, we can deploy a dummy contract and use its address. But the oracle is passed as initialization;
        // we cannot call initialize because it requires IController(msg.sender) and complex setup.
        // Since the bug is in oracle() itself, we can directly observe its behavior without initialization.
        // The mutant's oracle() has "require(false)" so it will always revert.
        // The reference oracle() returns the stored address (which defaults to address(0) if not initialized),
        // but since address(0) has no code, it might cause issues later, but for the view function call,
        // it returns address(0) without revert.
        // So the invariant is: calling oracle() never reverts.
        // We test this by wrapping the call in try/catch.
        bool ok;
        try c.oracle() returns (IOracleProvider) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

