pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(string memory name, string memory symbol) public {
        // Construct a minimal valid ProductInfo to initialize the contract.
        // We need a valid oracle (contract) and a valid payoff definition.
        // Deploy a minimal oracle contract that returns truthful data.
        // Since the oracle must be a contract, we deploy a helper.
        OracleMock oracle = new OracleMock();
        // PayoffDefinition: use a simple passthrough payoff (payoffType=0, direction=0, data=hex"")
        PayoffDefinition memory pd = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(0),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(0),
            data: bytes30(hex"")
        });

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: name,
            symbol: symbol,
            payoffDefinition: pd,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(0),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(0),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        // The initialize function requires msg.sender to be a controller (a contract).
        // We deploy a minimal controller mock that implements required functions.
        ControllerMock controllerMock = new ControllerMock();
        vm.prank(address(controllerMock));
        c.initialize(info);

        // Read the payoff definition from the contract.
        PayoffDefinition memory storedPd = c.payoffDefinition();

        // The general rule: the returned PayoffDefinition must equal the one we passed.
        // We compare the struct fields.
        assertTrue(
            storedPd.payoffType == pd.payoffType &&
            storedPd.payoffDirection == pd.payoffDirection &&
            storedPd.data == pd.data
        );
    }
}

