        );
        IProduct.ProductInfo memory productInfo = IProduct.ProductInfo(
            "Test",
            "TST",
            payoffDefinition,
            oracle,
            UFixed18.wrap(0.05e18),
            UFixed18.wrap(0.01e18),
            UFixed18.wrap(0.001e18),
            UFixed18.wrap(0.002e18),
            UFixed18.wrap(0.001e18),
