// Dummy implementations for Fixed18, UFixed18, PackedFixed18, PackedUFixed18, etc.
type Fixed18 is int256;
type PackedFixed18 is int128;
type UFixed18 is uint256;
type PackedUFixed18 is uint128;

library Fixed18Lib {
    int256 private constant BASE = 1e18;
    function wrap(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a); }
    function from(int256 a) internal pure returns (Fixed18) { return Fixed18.wrap(a * BASE); }
    function div(Fixed18 a, Fixed18 b) internal pure returns (Fixed18) { return Fixed18.wrap(Fixed18.unwrap(a) * BASE / Fixed18.unwrap(b)); }
    function from(int256 s, UFixed18 m) internal pure returns (Fixed18) { return Fixed18.wrap(0); }
}

using Fixed18Lib for Fixed18 global;

library UFixed18Lib {
    uint256 private constant BASE = 1e18;
    UFixed18 public constant ZERO = UFixed18.wrap(0);
    UFixed18 public constant ONE = UFixed18.wrap(BASE);
    function wrap(uint256 a) internal pure returns (UFixed18) { return UFixed18.wrap(a); }
    function mul(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return UFixed18.wrap(UFixed18.unwrap(a) * UFixed18.unwrap(b) / BASE); }
    function sub(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return UFixed18.wrap(UFixed18.unwrap(a) - UFixed18.unwrap(b)); }
    function gt(UFixed18 a, UFixed18 b) internal pure returns (bool) { return UFixed18.unwrap(a) > UFixed18.unwrap(b); }
    function max(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return UFixed18.wrap(UFixed18.unwrap(a) > UFixed18.unwrap(b) ? UFixed18.unwrap(a) : UFixed18.unwrap(b)); }
    function unsafeDiv(UFixed18 a, UFixed18 b) internal pure returns (UFixed18) { return UFixed18.wrap(0); }
    function abs(Fixed18 a) internal pure returns (UFixed18) { return UFixed18.wrap(0); }
    function isZero(UFixed18 a) internal pure returns (bool) { return UFixed18.unwrap(a) == 0; }
}

using UFixed18Lib for UFixed18 global;

